                    entity.getNavigation().moveTo(target, 1.3D);
                    if (dist < f + 1.0F) {
                        tryAnimation(entity.getRandom().nextBoolean() ? UnderzealotEntity.ANIMATION_ATTACK_0 : UnderzealotEntity.ANIMATION_ATTACK_1);
