                    if ((entity.getAnimation() == UnderzealotEntity.ANIMATION_ATTACK_0 || entity.getAnimation() == UnderzealotEntity.ANIMATION_ATTACK_1) && entity.getAnimationTick() == 8) {
                        checkAndDealDamage(target, 1.0F);
