@Override
    public void tick() {
        prevMotionX = getDeltaMovement().x;
        prevMotionY = getDeltaMovement().y;
        prevMotionZ = getDeltaMovement().z;

        super.tick();
        setDeltaMovement(getDeltaMovement().subtract(0, GRAVITY, 0));
        move(MoverType.SELF, getDeltaMovement());

        setYRot(-((float) Mth.atan2(getDeltaMovement().x, getDeltaMovement().z)) * (180F / (float)Math.PI));

        List<Entity> entitiesHit = getEntitiesNearby(1);
        if (!entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity instanceof ItemEntity) continue;
                if (entity == getCaster()) continue;
                if (entity instanceof EntityNaga) continue;
                if (entity instanceof ItemEntity) continue;
                if (entity.hurt(damageSources().indirectMagic(this, getCaster()), 3 * ConfigHandler.COMMON.MOBS.NAGA.combatConfig.attackMultiplier.get().floatValue()) && entity instanceof LivingEntity) {
                    ((LivingEntity)entity).addEffect(new MobEffectInstance(MobEffects.POISON, 80, 1, false, true));
                }
            }
        }

        if (!level().noCollision(this, getBoundingBox().inflate(0.1))) explode();

        if (level().isClientSide) {
            float scale = 1f;
            int steps = 4;
            double motionX = getDeltaMovement().x;
            double motionY = getDeltaMovement().y;
            double motionZ = getDeltaMovement().z;
            for (int step = 0; step < steps; step++) {
                double x = xo + step * (getX() - xo) / (double)steps;
                double y = yo + step * (getY() - yo) / (double)steps + getBbHeight() / 2f;
                double z = zo + step * (getZ() - zo) / (double)steps;
                for (int i = 0; i < 1; i++) {
                    double xSpeed = scale * 0.02 * (random.nextFloat() * 2 - 1);
                    double ySpeed = scale * 0.02 * (random.nextFloat() * 2 - 1);
                    double zSpeed = scale * 0.02 * (random.nextFloat() * 2 - 1);
                    double value = random.nextFloat() * 0.1f;
                    double life = random.nextFloat() * 10f + 15f;
                    ParticleVanillaCloudExtended.spawnVanillaCloud(level(), x - motionX * 0.5, y - motionY * 0.5, z - motionZ * 0.5, xSpeed, ySpeed, zSpeed, scale, 0.25d + value, 0.75d + value, 0.25d + value, 0.99, life);
                }
                for (int i = 0; i < 2; i++) {
                    double xSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                    double ySpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                    double zSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                    double value = random.nextFloat() * 0.1f;
                    double life = random.nextFloat() * 5f + 10f;
                    AdvancedParticleBase.spawnParticle(level(), ParticleHandler.PIXEL, x + xSpeed - motionX * 0.5, y + ySpeed - motionY * 0.5, z + zSpeed - motionZ * 0.5, xSpeed, ySpeed, zSpeed, true, 0, 0, 0, 0, scale * 3f, 0.07d + value, 0.25d + value, 0.07d + value, 1d, 0.99, life * 0.9, false, true);
                }
                for (int i = 0; i < 1; i++) {
                    if (random.nextFloat() < 0.9f) {
                        double xSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                        double ySpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                        double zSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                        double value = random.nextFloat() * 0.1f;
                        double life = random.nextFloat() * 5f + 10f;
                        AdvancedParticleBase.spawnParticle(level(), ParticleHandler.BUBBLE, x - motionX * 0.5, y - motionY * 0.5, z - motionZ * 0.5, xSpeed, ySpeed, zSpeed, true, 0, 0, 0, 0, 3f, 0.25d + value, 0.75d + value, 0.25d + value, 1d, 0.85, life, false, true);
                    }
                }
            }
        }
        if (tickCount > 50) discard() ;
    }

public LivingEntity getCaster() {
        if (this.cachedCaster != null && !this.cachedCaster.isRemoved()) {
            return this.cachedCaster;
        } else if (this.getCasterID().isPresent() && this.level() instanceof ServerLevel) {
            Entity entity = ((ServerLevel)this.level()).getEntity(this.getCasterID().get());
            if (entity instanceof LivingEntity) {
                cachedCaster = (LivingEntity) entity;
                PacketDistributor.sendToPlayersTrackingEntityAndSelf(this, MessageLinkEntities.fromEntity(this, cachedCaster));
            }
            return this.cachedCaster;
        } else {
            return null;
        }
    }

